    /*
     * Assign a Account
     * 
     * @param	parentId	UUID
     * @param	childId		UUID
     * @return	Transaction
     */
    public Transaction assignAccount( UUID parentId, UUID childId ) {
	    LOGGER.info("assigning Account as " + childId.toString());

	    Transaction parentEntity = repository.findById( parentId ).get();
		Account assignment = registry.project( Account.class, childId);

	    // ------------------------------------------
		// assign the Account to the parent entity
		// ------------------------------------------ 
	    parentEntity.setAccount( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Account
	 * 
	 * @param	parentId		UUID
	 * @return	Transaction
	 */
	public Transaction unAssignAccount( UUID parentId ) {
		Transaction parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Account on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Account on the parent entithy
		// ------------------------------------------     
	    parentEntity.setAccount(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}

