    /*
     * Add to the RelatedTransactions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Transaction
     */
    public Transaction addToRelatedTransactions( UUID parentId, List<UUID> children ) {
	    LOGGER.info("handling AssignRelatedTransactionsToTransactionEvent - " );
	    
	    Transaction parentEntity = repository.findById(parentId).get();

		for (UUID childId : children) {
			Transaction child = registry.project(Transaction.class, childId);
			parentEntity.getRelatedTransactions().add(child);
		}

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the RelatedTransactions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Transaction
     */
	public Transaction removeFromRelatedTransactions( UUID parentId, List<UUID> children ) {
	    LOGGER.info("handling RemoveRelatedTransactionsFromTransactionEvent " );
	    Transaction parentEntity = repository.findById(parentId).get();

		for (UUID childId : children) {
			Transaction child = registry.project(Transaction.class, childId);
			parentEntity.getRelatedTransactions().remove( child );
		}

	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

